// Los sub-workflows llamados con convertFieldsToString:true reciben los objetos
// como strings JSON. Se tolera cualquiera de las dos formas.
const asObj = (v) => {
  if (v === null || v === undefined) return {};
  if (typeof v === 'string') { const s = v.trim(); return s ? JSON.parse(s) : {}; }
  return v;
};

const j       = $input.first().json;
const payload = asObj(j.payload);
const context = asObj(j.context);

const invoiceId = Number(payload.invoice_id);

// Que falte el invoice_id NO es un error del hook: simplemente no hay nada que
// recalcular. Lanzar aquí ensuciaría hook_execution_log con errores que no lo son.
const valid = Number.isInteger(invoiceId) && invoiceId > 0;

return [{ json: {
  valid,
  invoice_id: valid ? invoiceId : null,
  clinic_id:  (context.clinic_id === null || context.clinic_id === undefined || context.clinic_id === '')
                ? null : Number(context.clinic_id),
  reason: valid ? null : 'payload.invoice_id ausente o inválido',
} }];

// Decide si hay algo que hacer y, sobre todo, si se pueden tocar las LÍNEAS.
const row = $input.first()?.json || {};
const ctx = $('Leer Contexto').first().json;

if (row.error || !row.invoice_id) {
  return [{ json: { apply: false, recalc_lines: false, invoice_id: ctx.invoice_id,
                    clinic_id: ctx.clinic_id,
                    reason: 'La factura no existe o no se pudo leer la política de descuentos' } }];
}

// Si el cliente no activó los descuentos, el hook no toca nada.
if (row.discounts_enabled !== true) {
  return [{ json: { apply: false, recalc_lines: false, invoice_id: ctx.invoice_id,
                    clinic_id: ctx.clinic_id,
                    reason: 'Descuentos deshabilitados en las preferencias de la clínica' } }];
}

// GUARDA DE CORRECCIÓN. Con ámbito 'total' el descuento de cabecera YA fue
// prorrateado entre las líneas por el flujo de ventas, así que
// invoice_items.discount_value no es la fuente de verdad: re-derivar las líneas
// desde ahí aplicaría el descuento dos veces y rompería el invariante
// invoices.total = SUM(invoice_items.total).
// En ese caso se hace sólo la consolidación de cabecera, que es una agregación
// pura y siempre segura.
const scope = row.invoice_scope || row.clinic_scope || 'line';

return [{ json: {
  apply: true,
  recalc_lines: scope !== 'total',
  invoice_id: ctx.invoice_id,
  clinic_id:  ctx.clinic_id,
  scope,
  reason: null,
} }];

const r = $input.first()?.json || {};

if (r.error) {
  // Se devuelve ok:false en vez de lanzar: el dispatcher lo registra en
  // hook_execution_log con el mensaje, y como este hook se registra con
  // on_error='ignore' la factura no se ve afectada.
  return [{ json: { ok: false, patch: {},
                    error: 'No se pudieron recalcular los descuentos: ' + (r.error?.message || r.error) } }];
}

const num = (v) => (v === null || v === undefined ? null : Number(v));

return [{ json: {
  ok: true,
  // El patch de un hook 'after' es informativo: el dispatcher no lo aplica.
  patch: {},
  message: `Factura ${r.doc_no || r.id}: bruto ${r.gross_total}, descuento ${r.discount_amount ?? 0}, neto ${r.total} (${r.lineas_actualizadas}/${r.lineas} líneas recalculadas)`,
  data: {
    invoice_id:          r.id,
    gross_total:         num(r.gross_total),
    total:               num(r.total),
    discount_amount:     num(r.discount_amount),
    discount_scope:      r.discount_scope,
    lineas:              Number(r.lineas || 0),
    lineas_actualizadas: Number(r.lineas_actualizadas || 0),
  },
} }];

// Camino "no hay nada que hacer". Devolver ok:true es lo correcto: el hook no
// falló, simplemente no aplicaba. Así hook_execution_log no se llena de errores
// falsos en las instalaciones que tienen los descuentos apagados.
const j = $input.first().json;
return [{ json: {
  ok: true,
  patch: {},
  message: j.reason || 'Sin cambios',
  data: { skipped: true, invoice_id: j.invoice_id ?? null },
} }];
